  const INLINED_MODAL_CSS = "/**\n * Poyori (ポヨリ) — Handheld Device Modal Stylesheet\n * Authentic 9-bit Retro RPG Dialogue & Console UI inspired by Image 2\n * PixelOperator typography, beveled pixel borders, high-contrast palette rendering,\n * and zero ABC hardware buttons.\n */\n\n.poyori-device-overlay {\n  position: fixed;\n  inset: 0;\n  background: rgba(10, 14, 22, 0.72);\n  backdrop-filter: blur(4px);\n  z-index: 2147483646;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-family: 'PixelOperator', monospace, sans-serif;\n  box-sizing: border-box;\n  pointer-events: auto !important;\n}\n\n/* ==========================================================================\n   9-Bit Retro Console / RPG Chassis\n   Beveled chocolate & amber-wood pixel frame inspired by Image 2\n   ========================================================================== */\n.poyori-device-shell {\n  width: 380px;\n  max-width: 95vw;\n  height: 560px;\n  max-height: 92vh;\n  background: #7a3c1c;\n  pointer-events: auto !important;\n  /* Double beveled pixel border */\n  border: 4px solid #24140e;\n  border-radius: 6px;\n  box-shadow: \n    inset 3px 3px 0 #d88344,\n    inset -3px -3px 0 #4a210f,\n    inset 6px 6px 0 #b35925,\n    inset -6px -6px 0 #311508,\n    0 16px 48px rgba(0, 0, 0, 0.75);\n  padding: 14px;\n  display: flex;\n  flex-direction: column;\n  position: relative;\n  box-sizing: border-box;\n  animation: poyoriPop 0.2s cubic-bezier(0.175, 0.885, 0.32, 1.275);\n}\n\n@keyframes poyoriPop {\n  0% { transform: scale(0.9); opacity: 0; }\n  100% { transform: scale(1); opacity: 1; }\n}\n\n/* Header with Title Ribbon Banner & LED */\n.poyori-device-header {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  margin-bottom: 8px;\n  padding: 0 4px;\n  gap: 8px;\n}\n\n/* Pulsing pixel power indicator gem */\n.poyori-power-led {\n  width: 10px;\n  height: 10px;\n  background: #55efc4;\n  border: 2px solid #24140e;\n  border-radius: 2px;\n  box-shadow: 0 0 6px #00b894, inset 1px 1px 0 #ffffff;\n  animation: ledPulse 1.8s infinite ease-in-out alternate;\n  flex-shrink: 0;\n}\n\n@keyframes ledPulse {\n  0% { opacity: 0.6; box-shadow: 0 0 2px #00b894; }\n  100% { opacity: 1; box-shadow: 0 0 8px #55efc4, 0 0 12px #00cec9; }\n}\n\n/* RPG Title Ribbon banner like in Image 2 */\n.poyori-title-banner {\n  flex: 1;\n  background: #3e1f13;\n  border: 2px solid #24140e;\n  border-radius: 4px;\n  padding: 4px 10px;\n  box-shadow: inset 1px 1px 0 #fedb72, inset -1px -1px 0 #1a0c06, 0 2px 0 rgba(0, 0, 0, 0.4);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n}\n\n.banner-text {\n  font-family: 'PixelOperator8', monospace;\n  font-size: 10px;\n  font-weight: bold;\n  color: #fedb72;\n  letter-spacing: 1px;\n  text-shadow: 1px 1px 0 #180b06;\n}\n\n.poyori-close-btn {\n  background: #8e2b24;\n  color: #ffffff;\n  border: 2px solid #24140e;\n  width: 24px;\n  height: 24px;\n  border-radius: 3px;\n  cursor: pointer;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  box-shadow: inset 1px 1px 0 #ea695f, inset -1px -1px 0 #4a1310, 0 2px 0 #000000;\n  transition: transform 0.05s;\n  flex-shrink: 0;\n}\n\n.poyori-close-btn:hover {\n  background: #b83329;\n}\n\n.poyori-close-btn:active {\n  transform: translateY(1px);\n  box-shadow: inset 1px 1px 0 #ea695f, 0 1px 0 #000000;\n}\n\n/* ==========================================================================\n   Screen Bezel & RPG Inventory Tab Bar\n   ========================================================================== */\n.poyori-screen-bezel {\n  flex: 1;\n  background: #24140e;\n  border-radius: 6px;\n  padding: 8px;\n  border: 3px solid #140b07;\n  box-shadow: inset 0 3px 8px rgba(0, 0, 0, 0.85);\n  display: flex;\n  flex-direction: column;\n  overflow: hidden;\n  gap: 8px;\n}\n\n/* Tabs Bar styled like RPG inventory slots */\n.poyori-tabs-bar {\n  display: flex;\n  justify-content: space-between;\n  background: #140b07;\n  border-radius: 4px;\n  padding: 3px;\n  border: 2px solid #361c10;\n  gap: 4px;\n}\n\n.poyori-tab-btn {\n  flex: 1;\n  background: #2b170e;\n  border: 2px solid #140b07;\n  border-radius: 3px;\n  padding: 5px 2px;\n  cursor: pointer;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  box-shadow: inset 1px 1px 0 #5a2e17, inset -1px -1px 0 #0f0704;\n  transition: all 0.1s;\n}\n\n.poyori-tab-btn:hover {\n  background: #3e2215;\n}\n\n.poyori-tab-btn.active {\n  background: var(--screen-bg, #9bbc0f);\n  border-color: #fedb72;\n  box-shadow: inset 1px 1px 0 #ffffff, 0 0 6px #fedb72;\n}\n\n/* ==========================================================================\n   LCD Screen / Dialogue Area with High-Contrast Guarantees\n   ========================================================================== */\n.poyori-lcd-screen {\n  flex: 1;\n  background: var(--screen-bg, #9bbc0f);\n  color: var(--screen-text, #0f380f);\n  border-radius: 4px;\n  border: 2px solid #000000;\n  box-shadow: inset 0 2px 6px rgba(0, 0, 0, 0.4);\n  padding: 10px;\n  overflow-y: auto;\n  position: relative;\n  font-family: 'PixelOperator', monospace;\n  font-size: 13px;\n  line-height: 1.35;\n  image-rendering: pixelated;\n}\n\n/* Subtle retro scanlines */\n.poyori-lcd-screen::after {\n  content: \"\";\n  position: absolute;\n  inset: 0;\n  background: linear-gradient(rgba(0, 0, 0, 0) 50%, rgba(0, 0, 0, 0.05) 50%);\n  background-size: 100% 3px;\n  pointer-events: none;\n}\n\n/* ==========================================================================\n   Status View & Direct Care Actions\n   ========================================================================== */\n.poyori-status-view {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n}\n\n/* Pet Portrait Frame with Stage and Mood Containers on Left */\n.poyori-pet-portrait {\n  display: flex;\n  flex-direction: row;\n  align-items: center;\n  justify-content: space-between;\n  background: var(--screen-card-bg, rgba(0, 0, 0, 0.07));\n  padding: 8px 12px;\n  border-radius: 4px;\n  border: 2px solid var(--screen-card-border, rgba(0, 0, 0, 0.2));\n  box-shadow: inset 1px 1px 0 rgba(255, 255, 255, 0.15), inset -1px -1px 0 rgba(0, 0, 0, 0.2);\n  gap: 12px;\n}\n\n.poyori-portrait-meta-left {\n  display: flex;\n  flex-direction: column;\n  align-items: flex-start;\n  justify-content: center;\n  gap: 6px;\n  flex: 1;\n}\n\n.poyori-portrait-creature-center {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  flex: 1.2;\n}\n\n.poyori-screen-sprite {\n  width: 64px;\n  height: 64px;\n  image-rendering: pixelated;\n  filter: drop-shadow(0 2px 4px rgba(0, 0, 0, 0.25));\n}\n\n.poyori-pet-name {\n  font-family: 'PixelOperator8', monospace;\n  font-size: 11px;\n  font-weight: bold;\n  margin-top: 4px;\n  color: var(--screen-text, #0f380f);\n  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.15);\n  display: flex;\n  align-items: center;\n  gap: 4px;\n}\n\n.poyori-badge-tag {\n  font-family: 'PixelOperator8', monospace;\n  font-size: 8px;\n  background: var(--screen-mid, #c67232);\n  color: #ffffff;\n  padding: 3px 6px;\n  border-radius: 2px;\n  border: 1px solid var(--screen-card-border, rgba(0, 0, 0, 0.2));\n  text-shadow: 1px 1px 0 rgba(0, 0, 0, 0.4);\n  box-shadow: inset 1px 1px 0 rgba(255, 255, 255, 0.2), 0 1px 2px rgba(0, 0, 0, 0.2);\n}\n\n/* Direct Care Action Bar (Replaces defunct ABC hardware buttons) */\n.poyori-direct-care-bar {\n  display: flex;\n  gap: 6px;\n}\n\n.poyori-care-btn {\n  flex: 1;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  gap: 5px;\n  padding: 6px 4px;\n  border-radius: 3px;\n  border: 2px solid #24140e;\n  font-family: 'PixelOperator8', monospace;\n  font-size: 8px;\n  font-weight: bold;\n  cursor: pointer;\n  color: #ffffff;\n  text-shadow: 1px 1px 0 #140b07;\n  transition: transform 0.05s;\n}\n\n.poyori-care-btn:active {\n  transform: translateY(2px);\n}\n\n.poyori-care-btn.feed {\n  background: #d63d2f;\n  box-shadow: inset 1px 1px 0 #ea695f, inset -1px -1px 0 #5a1714, 0 2px 0 #140b07;\n}\n.poyori-care-btn.feed:hover { background: #e54c3e; }\n\n.poyori-care-btn.pet {\n  background: #e67e22;\n  box-shadow: inset 1px 1px 0 #f39c12, inset -1px -1px 0 #6e390c, 0 2px 0 #140b07;\n}\n.poyori-care-btn.pet:hover { background: #f39c12; }\n\n.poyori-care-btn.sleep {\n  background: #2980b9;\n  box-shadow: inset 1px 1px 0 #3498db, inset -1px -1px 0 #133d59, 0 2px 0 #140b07;\n}\n.poyori-care-btn.sleep:hover { background: #3498db; }\n\n.poyori-care-btn.pocket {\n  background: #6c5ce7;\n  box-shadow: inset 1px 1px 0 #a29bfe, inset -1px -1px 0 #341f97, 0 2px 0 #140b07;\n}\n.poyori-care-btn.pocket:hover { background: #7d6cf0; }\n.poyori-care-btn.pocket.active {\n  background: #d88344;\n  box-shadow: inset 1px 1px 0 #fedb72, inset -1px -1px 0 #7e3e13, 0 2px 0 #140b07;\n}\n\n/* Vitals Card & High-Contrast Rows */\n.poyori-vitals-card {\n  display: flex;\n  flex-direction: column;\n  gap: 5px;\n  background: var(--screen-card-bg, rgba(0, 0, 0, 0.07));\n  padding: 8px;\n  border-radius: 4px;\n  border: 2px solid var(--screen-card-border, rgba(0, 0, 0, 0.2));\n  box-shadow: inset 1px 1px 0 rgba(255, 255, 255, 0.1);\n}\n\n.poyori-vital-row {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  font-size: 12px;\n}\n\n.poyori-vital-row .v-label {\n  color: var(--screen-label, #8c3d12);\n  font-weight: bold;\n  font-family: 'PixelOperator', monospace;\n}\n\n.poyori-vital-row .v-val {\n  color: var(--screen-text, #24140e);\n  display: flex;\n  align-items: center;\n  gap: 3px;\n  font-weight: bold;\n}\n\n/* Grooved XP Progress Bar */\n.poyori-xp-bar-wrap {\n  margin-top: 6px;\n}\n\n.poyori-xp-label {\n  display: flex;\n  justify-content: space-between;\n  font-family: 'PixelOperator8', monospace;\n  font-size: 8px;\n  color: var(--screen-label, #8c3d12);\n  margin-bottom: 3px;\n  font-weight: bold;\n}\n\n.poyori-xp-track {\n  height: 10px;\n  background: rgba(0, 0, 0, 0.35);\n  border: 2px solid var(--screen-card-border, #24140e);\n  border-radius: 2px;\n  overflow: hidden;\n  box-shadow: inset 0 2px 4px rgba(0, 0, 0, 0.5);\n}\n\n.poyori-xp-fill {\n  height: 100%;\n  background: var(--screen-mid, #306230);\n  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.4);\n}\n\n/* ==========================================================================\n   Tasks, Food, Almanac, Wardrobe, and Settings Views\n   ========================================================================== */\n.poyori-tasks-view,\n.poyori-food-view,\n.poyori-zukan-view,\n.poyori-wardrobe-view,\n.poyori-settings-view {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n}\n\n.poyori-subhead {\n  font-family: 'PixelOperator8', monospace;\n  font-size: 9px;\n  color: var(--screen-label, #8c3d12);\n  border-bottom: 2px solid var(--screen-card-border, rgba(0, 0, 0, 0.25));\n  padding-bottom: 4px;\n  display: flex;\n  align-items: center;\n  gap: 5px;\n  font-weight: bold;\n}\n\n/* Tasks */\n.poyori-add-task-row {\n  display: flex;\n  gap: 4px;\n}\n\n.poyori-add-task-row input {\n  flex: 1;\n  background: #ffffff;\n  color: #1a1a1a;\n  border: 2px solid var(--screen-card-border, #24140e);\n  padding: 4px 6px;\n  font-size: 13px;\n  font-family: inherit;\n  border-radius: 3px;\n  box-shadow: inset 1px 1px 3px rgba(0, 0, 0, 0.15);\n}\n\n.poyori-add-task-row button {\n  background: var(--screen-mid, #306230);\n  color: #ffffff;\n  border: 2px solid #24140e;\n  padding: 4px 8px;\n  font-size: 9px;\n  font-family: 'PixelOperator8', monospace;\n  border-radius: 3px;\n  cursor: pointer;\n  box-shadow: inset 1px 1px 0 rgba(255,255,255,0.3), 0 2px 0 #140b07;\n}\n\n.poyori-task-list {\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n  max-height: 120px;\n  overflow-y: auto;\n}\n\n.poyori-task-item {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  background: var(--screen-card-bg, rgba(0, 0, 0, 0.08));\n  border: 1px solid var(--screen-card-border, rgba(0, 0, 0, 0.2));\n  color: var(--screen-text, #24140e);\n  padding: 5px 6px;\n  border-radius: 3px;\n  font-size: 12px;\n}\n\n.poyori-task-item.done {\n  text-decoration: line-through;\n  opacity: 0.6;\n}\n\n.task-title {\n  flex: 1;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  color: var(--screen-text, #24140e);\n}\n\n.task-reward {\n  font-family: 'PixelOperator8', monospace;\n  font-size: 8px;\n  color: var(--screen-label, #8c3d12);\n  font-weight: bold;\n  display: flex;\n  align-items: center;\n  gap: 3px;\n}\n\n.task-del-btn {\n  background: transparent;\n  border: none;\n  cursor: pointer;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n}\n\n.poyori-quest-item {\n  background: var(--screen-card-bg, rgba(0, 0, 0, 0.08));\n  border: 1px solid var(--screen-card-border, rgba(0, 0, 0, 0.2));\n  color: var(--screen-text, #24140e);\n  padding: 6px;\n  border-radius: 3px;\n  margin-bottom: 5px;\n}\n\n.quest-title {\n  color: var(--screen-label, #8c3d12);\n  font-weight: bold;\n  font-size: 11px;\n  display: flex;\n  align-items: center;\n  gap: 4px;\n}\n\n.quest-bar {\n  height: 6px;\n  background: rgba(0, 0, 0, 0.3);\n  border: 1px solid var(--screen-card-border, #24140e);\n  border-radius: 2px;\n  overflow: hidden;\n  margin: 3px 0;\n}\n\n.quest-fill {\n  height: 100%;\n  background: var(--screen-mid, #306230);\n}\n\n.quest-status {\n  color: var(--screen-text, #24140e);\n  font-size: 10px;\n}\n\n/* Food View */\n.poyori-food-grid {\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n}\n\n.poyori-food-card {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  background: var(--screen-card-bg, rgba(0, 0, 0, 0.08));\n  border: 2px solid var(--screen-card-border, rgba(0, 0, 0, 0.2));\n  color: var(--screen-text, #24140e);\n  padding: 6px 8px;\n  border-radius: 4px;\n}\n\n.food-icon {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n}\n\n.food-info { flex: 1; }\n.food-name {\n  font-family: 'PixelOperator8', monospace;\n  font-size: 9px;\n  color: var(--screen-label, #8c3d12);\n  font-weight: bold;\n}\n.food-desc {\n  font-size: 11px;\n  color: var(--screen-text, #24140e);\n  opacity: 0.9;\n}\n.food-boosts {\n  font-size: 11px;\n  color: var(--screen-text, #24140e);\n  font-weight: bold;\n}\n\n.food-action {\n  display: flex;\n  flex-direction: column;\n  align-items: flex-end;\n  gap: 3px;\n}\n\n.food-count {\n  font-family: 'PixelOperator8', monospace;\n  font-size: 8px;\n  color: var(--screen-text, #24140e);\n}\n\n.feed-btn {\n  background: #27ae60;\n  color: #ffffff;\n  border: 2px solid #24140e;\n  padding: 3px 8px;\n  font-size: 8px;\n  font-family: 'PixelOperator8', monospace;\n  border-radius: 3px;\n  cursor: pointer;\n  box-shadow: inset 1px 1px 0 rgba(255,255,255,0.4), 0 2px 0 #140b07;\n}\n\n.feed-btn:disabled {\n  opacity: 0.5;\n  cursor: not-allowed;\n}\n\n/* ==========================================================================\n   Price Indicator Badges (Golden Koban Pixel Tag)\n   Dark slate background (#1c130e), 1px golden pixel border (#fedb72),\n   pixelated Koban coin icon, and bright golden PixelOperator8 typography\n   ========================================================================== */\n.price-indicator-badge,\n.buy-food-btn {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  gap: 4px;\n  background: #1c130e;\n  border: 1px solid #fedb72;\n  border-radius: 3px;\n  padding: 3px 6px;\n  color: #fedb72;\n  font-family: 'PixelOperator8', monospace;\n  font-size: 8px;\n  line-height: 1;\n  letter-spacing: 0.5px;\n  box-shadow: 0 1px 0 #000000, inset 0 0 4px rgba(254, 219, 114, 0.15);\n  cursor: pointer;\n  image-rendering: pixelated;\n  -webkit-font-smoothing: none;\n  transition: transform 0.04s ease, box-shadow 0.04s ease, background 0.1s ease;\n  user-select: none;\n  text-decoration: none;\n}\n\n.price-indicator-badge:hover,\n.buy-food-btn:hover {\n  background: #2a1b12;\n  border-color: #fff2b8;\n  color: #fff2b8;\n  box-shadow: 0 1px 0 #000000, 0 0 6px rgba(254, 219, 114, 0.4);\n}\n\n.price-indicator-badge:active,\n.buy-food-btn:active {\n  transform: translateY(1px);\n  box-shadow: 0 0 0 #000000;\n}\n\n.price-indicator-badge:disabled,\n.buy-food-btn:disabled {\n  opacity: 0.45;\n  cursor: not-allowed;\n  border-color: #554433;\n  color: #887766;\n  box-shadow: none;\n  transform: none;\n}\n\n.price-coin-icon {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  line-height: 0;\n}\n\n.price-coin-icon img {\n  image-rendering: pixelated;\n}\n\n.price-value {\n  font-family: 'PixelOperator8', monospace;\n  font-size: 8px;\n  line-height: 1;\n}\n\n/* Bestiary / Almanac View */\n.poyori-zukan-list {\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n}\n\n.poyori-zukan-entry {\n  display: flex;\n  gap: 8px;\n  align-items: center;\n  background: var(--screen-card-bg, rgba(0, 0, 0, 0.08));\n  border: 2px solid var(--screen-card-border, rgba(0, 0, 0, 0.2));\n  color: var(--screen-text, #24140e);\n  padding: 6px 8px;\n  border-radius: 4px;\n}\n\n.zukan-img {\n  width: 40px;\n  height: 40px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n}\n\n.zukan-img img {\n  width: 36px;\n  height: 36px;\n  image-rendering: pixelated;\n}\n\n.zukan-meta { flex: 1; }\n.zukan-name {\n  font-family: 'PixelOperator8', monospace;\n  font-size: 9px;\n  color: var(--screen-label, #8c3d12);\n  font-weight: bold;\n}\n.zukan-branch {\n  font-size: 11px;\n  color: var(--screen-text, #24140e);\n  opacity: 0.85;\n}\n.zukan-desc {\n  font-size: 12px;\n  color: var(--screen-text, #24140e);\n}\n\n.zukan-info-banner {\n  background: var(--screen-card-bg, rgba(0, 0, 0, 0.08));\n  border: 1px dashed var(--screen-label, #8c3d12);\n  color: var(--screen-text, #24140e);\n  padding: 6px;\n  border-radius: 3px;\n  font-size: 11px;\n  text-align: center;\n}\n\n/* Wardrobe View */\n.poyori-wardrobe-grid {\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n}\n\n.poyori-wardrobe-item {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  background: var(--screen-card-bg, rgba(0, 0, 0, 0.08));\n  border: 2px solid var(--screen-card-border, rgba(0, 0, 0, 0.2));\n  color: var(--screen-text, #24140e);\n  padding: 6px 8px;\n  border-radius: 4px;\n}\n\n.wardrobe-icon {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n}\n\n.wardrobe-info { flex: 1; }\n.wardrobe-name {\n  font-family: 'PixelOperator8', monospace;\n  font-size: 9px;\n  color: var(--screen-label, #8c3d12);\n  font-weight: bold;\n}\n.wardrobe-cost {\n  font-size: 11px;\n  color: var(--screen-text, #24140e);\n  display: flex;\n  align-items: center;\n  gap: 3px;\n}\n\n.equipped-tag {\n  font-family: 'PixelOperator8', monospace;\n  font-size: 8px;\n  color: #27ae60;\n  font-weight: bold;\n}\n\n.equip-btn, .buy-btn {\n  background: var(--screen-mid, #306230);\n  color: #ffffff;\n  border: 2px solid #24140e;\n  padding: 3px 8px;\n  font-size: 8px;\n  font-family: 'PixelOperator8', monospace;\n  border-radius: 3px;\n  cursor: pointer;\n  box-shadow: inset 1px 1px 0 rgba(255,255,255,0.4), 0 2px 0 #140b07;\n}\n\n.poyori-palette-row {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 4px;\n}\n\n.palette-swatch-btn {\n  border: 2px solid #24140e;\n  border-radius: 3px;\n  padding: 4px 6px;\n  font-family: 'PixelOperator8', monospace;\n  font-size: 8px;\n  cursor: pointer;\n  box-shadow: inset 1px 1px 0 rgba(255,255,255,0.4), 0 2px 0 #140b07;\n}\n\n.palette-swatch-btn.active {\n  box-shadow: inset 0 0 0 2px #fedb72, 0 0 6px #fedb72;\n}\n\n/* Settings View */\n.settings-row {\n  display: flex;\n  flex-direction: column;\n  gap: 3px;\n  font-size: 12px;\n  margin-bottom: 6px;\n}\n\n.settings-row label {\n  color: var(--screen-label, #8c3d12);\n  font-weight: bold;\n}\n\n.settings-row select,\n.settings-row input[type=\"text\"],\n.settings-row input[type=\"time\"] {\n  background: #ffffff;\n  color: #1a1a1a;\n  border: 2px solid var(--screen-card-border, #24140e);\n  padding: 4px 6px;\n  font-size: 12px;\n  border-radius: 3px;\n  font-family: inherit;\n  box-shadow: inset 1px 1px 3px rgba(0, 0, 0, 0.15);\n}\n\n.time-inputs {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n}\n\n.poyori-btn-primary {\n  background: var(--screen-mid, #306230);\n  color: #ffffff;\n  border: 2px solid #24140e;\n  padding: 6px;\n  font-size: 9px;\n  font-family: 'PixelOperator8', monospace;\n  border-radius: 3px;\n  cursor: pointer;\n  box-shadow: inset 1px 1px 0 rgba(255,255,255,0.4), 0 2px 0 #140b07;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  gap: 6px;\n}\n\n.poyori-btn-primary:active {\n  transform: translateY(2px);\n  box-shadow: 0 1px 0 #140b07;\n}\n\n/* ==========================================================================\n   Tactile 9-Bit Handheld Console Buttons (A, B, C)\n   Keycap styling inspired by Image 2 with clear functional roles\n   ========================================================================== */\n.poyori-console-controls {\n  display: flex;\n  justify-content: space-evenly;\n  align-items: center;\n  margin-top: 10px;\n  padding: 8px 10px;\n  background: #180d09;\n  border-radius: 6px;\n  border: 2px solid #0a0503;\n  box-shadow: inset 0 3px 6px rgba(0, 0, 0, 0.8), 0 1px 0 rgba(255, 255, 255, 0.08);\n  gap: 10px;\n}\n\n.poyori-console-btn {\n  flex: 1;\n  height: 40px;\n  border-radius: 4px;\n  border: 2px solid #0a0503;\n  cursor: pointer;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  position: relative;\n  transition: transform 0.04s ease, box-shadow 0.04s ease, border-color 0.1s ease, background 0.1s ease;\n  pointer-events: auto !important;\n  user-select: none;\n  image-rendering: pixelated;\n  -webkit-font-smoothing: none;\n  background: #241b16;\n  color: #fedb72;\n  box-shadow: inset 1px 1px 0 rgba(255, 255, 255, 0.18), inset -1px -1px 0 #120b08, 0 4px 0 #000000;\n}\n\n.poyori-console-btn:hover {\n  background: #2e231c;\n  color: #fff2b8;\n  border-color: #45b7b8;\n  box-shadow: inset 1px 1px 0 rgba(255, 255, 255, 0.28), inset -1px -1px 0 #120b08, 0 4px 0 #000000, 0 0 8px rgba(69, 183, 184, 0.45);\n}\n\n.poyori-console-btn:active {\n  transform: translateY(3px);\n  box-shadow: inset 1px 1px 0 #0a0503, inset -1px -1px 0 rgba(255, 255, 255, 0.08), 0 1px 0 #000000;\n}\n\n.console-btn-label {\n  font-family: 'PixelOperator8', 'PixelOperator', monospace !important;\n  font-size: 8.5px !important;\n  font-weight: bold !important;\n  letter-spacing: 0.8px !important;\n  line-height: 1 !important;\n  text-shadow: 1px 1px 0 #000000;\n  -webkit-font-smoothing: none !important;\n  image-rendering: pixelated;\n}\n\n/* Backward-compatibility aliases for legacy templates */\n.btn-letter,\n.btn-subtext {\n  font-family: 'PixelOperator8', 'PixelOperator', monospace !important;\n  font-size: 8px !important;\n  font-weight: bold !important;\n  letter-spacing: 0.5px !important;\n  -webkit-font-smoothing: none !important;\n  image-rendering: pixelated;\n}\n\n/* ==========================================================================\n   Mood Badges, Fixed Rewards, & Blocked Site Manager\n   ========================================================================== */\n.poyori-mood-tag {\n  font-family: 'PixelOperator8', monospace;\n  font-size: 8px;\n  padding: 2px 6px;\n  border-radius: 3px;\n  margin-top: 3px;\n  border: 1px solid var(--screen-card-border, rgba(0, 0, 0, 0.2));\n  display: flex;\n  align-items: center;\n  gap: 4px;\n  font-weight: bold;\n}\n\n.poyori-mood-tag.cheerful {\n  background: #27ae60;\n  color: #ffffff;\n}\n\n.poyori-mood-tag.grumpy {\n  background: #e17055;\n  color: #ffffff;\n  animation: grumpyPuff 1s infinite alternate;\n}\n\n@keyframes grumpyPuff {\n  0% { transform: scale(1); }\n  100% { transform: scale(1.04); }\n}\n\n.poyori-mood-tag.sleepy {\n  background: #2980b9;\n  color: #ffffff;\n}\n\n.poyori-mood-tag.sick {\n  background: #d63031;\n  color: #ffffff;\n}\n\n/* Fixed Reward Callout */\n.task-fixed-reward-callout {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  background: var(--screen-card-bg, rgba(0, 0, 0, 0.08));\n  border: 1px dashed var(--screen-label, #8c3d12);\n  padding: 4px 8px;\n  border-radius: 3px;\n  font-family: 'PixelOperator8', monospace;\n  font-size: 8px;\n  color: var(--screen-label, #8c3d12);\n  margin-top: 2px;\n  margin-bottom: 4px;\n}\n\n.callout-badges {\n  display: flex;\n  align-items: center;\n  gap: 4px;\n  color: var(--screen-text);\n  font-weight: bold;\n}\n\n/* Checkbox Lines */\n.checkbox-line {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  font-size: 12px;\n  color: var(--screen-text);\n}\n\n/* Custom Blocked Sites Container */\n.poyori-add-blocked-row {\n  display: flex;\n  gap: 4px;\n  margin-bottom: 4px;\n}\n\n.poyori-add-blocked-row input {\n  flex: 1;\n  background: #ffffff;\n  color: #1a1a1a;\n  border: 2px solid var(--screen-card-border, #24140e);\n  padding: 4px 6px;\n  font-size: 12px;\n  border-radius: 3px;\n}\n\n.poyori-add-blocked-row button {\n  background: #d63031;\n  color: #ffffff;\n  border: 2px solid #24140e;\n  padding: 4px 8px;\n  font-size: 8px;\n  font-family: 'PixelOperator8', monospace;\n  border-radius: 3px;\n  cursor: pointer;\n  box-shadow: inset 1px 1px 0 rgba(255,255,255,0.4), 0 2px 0 #140b07;\n}\n\n.poyori-blocked-tags-container {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 4px;\n  max-height: 80px;\n  overflow-y: auto;\n  background: rgba(0, 0, 0, 0.06);\n  padding: 4px;\n  border-radius: 3px;\n  border: 1px solid var(--screen-card-border, rgba(0, 0, 0, 0.15));\n}\n\n.blocked-site-tag {\n  display: flex;\n  align-items: center;\n  gap: 4px;\n  background: #24140e;\n  color: #fedb72;\n  border: 1px solid #140b07;\n  padding: 2px 6px;\n  border-radius: 2px;\n  font-size: 11px;\n}\n\n.del-blocked-btn {\n  background: transparent;\n  border: none;\n  cursor: pointer;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  padding: 0;\n}\n\n\n\n/* Cure Medicine Button */\n.poyori-care-btn.cure {\n  background: #27ae60;\n  box-shadow: inset 1px 1px 0 #2ecc71, inset -1px -1px 0 #196f3d, 0 2px 0 #140b07;\n  animation: pulse-cure 1.2s infinite ease-in-out;\n}\n.poyori-care-btn.cure:hover { background: #2ecc71; }\n\n@keyframes pulse-cure {\n  0%, 100% { transform: scale(1); }\n  50% { transform: scale(1.04); box-shadow: 0 0 6px #2ecc71; }\n}\n\n/* Breed & Level Tags */\n.poyori-breed-tag {\n  font-family: 'PixelOperator8', monospace;\n  font-size: 7px;\n  background: rgba(0, 0, 0, 0.15);\n  color: var(--screen-text, #0f380f);\n  padding: 2px 5px;\n  border-radius: 2px;\n  border: 1px solid var(--screen-card-border, rgba(0, 0, 0, 0.2));\n  letter-spacing: 0.5px;\n}\n\n.poyori-creature-species {\n  font-family: 'PixelOperator8', monospace;\n  font-size: 8px;\n  color: var(--screen-text, #0f380f);\n  opacity: 0.85;\n  margin-top: 2px;\n}\n\n/* Focus Session Tab */\n.poyori-focus-view {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n}\n\n.poyori-focus-timer-box {\n  background: var(--screen-card-bg, rgba(0, 0, 0, 0.08));\n  border: 2px solid var(--screen-card-border, rgba(0, 0, 0, 0.2));\n  border-radius: 5px;\n  padding: 12px 10px;\n  text-align: center;\n}\n\n.focus-section-label {\n  font-family: 'PixelOperator8', monospace;\n  font-size: 8px;\n  color: var(--screen-label, #8c3d12);\n  font-weight: bold;\n  text-align: left;\n  margin-bottom: 6px;\n}\n\n.poyori-focus-digits {\n  font-family: 'PixelOperator8', monospace;\n  font-size: 26px;\n  font-weight: bold;\n  letter-spacing: 2px;\n  color: var(--screen-text, #0f380f);\n  margin: 8px 0;\n  text-shadow: 0 2px 4px rgba(0, 0, 0, 0.2);\n}\n\n.focus-active-badge {\n  font-family: 'PixelOperator8', monospace;\n  font-size: 8px;\n  color: #fedb72;\n  font-weight: bold;\n  letter-spacing: 0.5px;\n  margin-bottom: 4px;\n}\n\n.focus-progress-wrap {\n  width: 100%;\n  height: 8px;\n  background: rgba(0, 0, 0, 0.25);\n  border: 1px solid var(--screen-card-border, rgba(0, 0, 0, 0.3));\n  border-radius: 4px;\n  overflow: hidden;\n  margin: 6px 0 10px 0;\n}\n\n.focus-progress-bar {\n  height: 100%;\n  background: linear-gradient(90deg, #27ae60, #2ecc71);\n  transition: width 0.3s ease;\n}\n\n.focus-guard-status {\n  font-family: 'PixelOperator8', monospace;\n  font-size: 7.5px;\n  color: #27ae60;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  gap: 4px;\n  font-weight: bold;\n}\n\n.focus-distractions-pill {\n  font-family: 'PixelOperator8', monospace;\n  font-size: 7px;\n  margin-top: 4px;\n  opacity: 0.85;\n  color: var(--screen-text, #0f380f);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  gap: 4px;\n}\n\n.poyori-discipline-grid {\n  display: grid;\n  grid-template-columns: repeat(2, 1fr);\n  gap: 6px;\n  margin-top: 4px;\n}\n\n.discipline-btn {\n  display: flex;\n  flex-direction: column;\n  align-items: flex-start;\n  justify-content: center;\n  gap: 2px;\n  padding: 8px 6px;\n  font-family: 'PixelOperator8', monospace;\n  font-size: 8px;\n  background: var(--screen-card-bg, rgba(0, 0, 0, 0.05));\n  border: 1.5px solid var(--screen-card-border, rgba(0, 0, 0, 0.2));\n  border-radius: 4px;\n  cursor: pointer;\n  color: var(--screen-text, #0f380f);\n  transition: all 0.1s;\n  text-align: left;\n}\n\n.discipline-btn:hover {\n  border-color: #45b7b8;\n  background: rgba(69, 183, 184, 0.15);\n}\n\n.discipline-btn.active {\n  background: #2980b9;\n  color: #ffffff;\n  border-color: #45b7b8;\n  box-shadow: 0 0 8px rgba(69, 183, 184, 0.45);\n  text-shadow: 1px 1px 0 rgba(0, 0, 0, 0.4);\n}\n\n.discipline-title-row {\n  display: flex;\n  align-items: center;\n  gap: 5px;\n  font-weight: bold;\n}\n\n.discipline-name {\n  font-size: 8px;\n}\n\n.discipline-lineage {\n  font-size: 6.5px;\n  opacity: 0.85;\n  letter-spacing: 0.3px;\n}\n\n.duration-selector {\n  display: flex;\n  gap: 6px;\n  margin-top: 4px;\n}\n\n.duration-btn {\n  flex: 1;\n  padding: 8px 2px;\n  font-family: 'PixelOperator8', monospace;\n  font-size: 8px;\n  border: 1.5px solid var(--screen-card-border, rgba(0, 0, 0, 0.2));\n  border-radius: 4px;\n  background: var(--screen-card-bg, rgba(0, 0, 0, 0.05));\n  color: var(--screen-text, #0f380f);\n  cursor: pointer;\n  transition: all 0.1s;\n  text-align: center;\n}\n\n.duration-btn:hover {\n  border-color: #fedb72;\n}\n\n.duration-btn.active {\n  background: #e67e22;\n  color: #ffffff;\n  border-color: #fedb72;\n  box-shadow: 0 0 6px rgba(254, 219, 114, 0.4);\n  font-weight: bold;\n}\n\n.start-focus-btn {\n  width: 100%;\n  padding: 10px;\n  margin-top: 10px;\n  font-family: 'PixelOperator8', monospace;\n  font-size: 9.5px;\n  font-weight: bold;\n  background: #27ae60;\n  color: #ffffff;\n  border: 2px solid #140b07;\n  border-radius: 4px;\n  cursor: pointer;\n  box-shadow: 0 3px 0 #140b07;\n  text-shadow: 1px 1px 0 #140b07;\n  transition: transform 0.04s, box-shadow 0.04s;\n}\n\n.start-focus-btn:hover {\n  background: #2ecc71;\n}\n\n.start-focus-btn:active {\n  transform: translateY(2px);\n  box-shadow: 0 1px 0 #140b07;\n}\n\n.stop-focus-btn {\n  width: 100%;\n  padding: 10px;\n  margin-top: 10px;\n  font-family: 'PixelOperator8', monospace;\n  font-size: 9.5px;\n  font-weight: bold;\n  background: #c0392b;\n  color: #ffffff;\n  border: 2px solid #140b07;\n  border-radius: 4px;\n  cursor: pointer;\n  box-shadow: 0 3px 0 #140b07;\n  text-shadow: 1px 1px 0 #140b07;\n  transition: transform 0.04s, box-shadow 0.04s;\n}\n\n.stop-focus-btn:hover {\n  background: #e74c3c;\n}\n\n.stop-focus-btn:active {\n  transform: translateY(2px);\n  box-shadow: 0 1px 0 #140b07;\n}\n\n.focus-rewards-card {\n  background: var(--screen-card-bg, rgba(0, 0, 0, 0.06));\n  border: 1px dashed var(--screen-card-border, rgba(0, 0, 0, 0.3));\n  border-radius: 4px;\n  padding: 8px 10px;\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n}\n\n.rewards-card-header {\n  font-family: 'PixelOperator8', monospace;\n  font-size: 7.5px;\n  font-weight: bold;\n  color: var(--screen-label, #8c3d12);\n  display: flex;\n  align-items: center;\n  gap: 4px;\n}\n\n.rewards-row {\n  display: flex;\n  gap: 6px;\n}\n\n.reward-pill {\n  font-family: 'PixelOperator8', monospace;\n  font-size: 7px;\n  background: rgba(0, 0, 0, 0.1);\n  border: 1px solid var(--screen-card-border, rgba(0, 0, 0, 0.2));\n  padding: 3px 6px;\n  border-radius: 3px;\n  display: inline-flex;\n  align-items: center;\n  gap: 4px;\n  color: var(--screen-text, #0f380f);\n  font-weight: bold;\n}\n\n.focus-shield-status {\n  font-family: 'PixelOperator8', monospace;\n  font-size: 6.5px;\n  color: #27ae60;\n  display: flex;\n  align-items: center;\n  gap: 4px;\n  line-height: 1.2;\n}\n\n.focus-stats-row {\n  font-family: 'PixelOperator8', monospace;\n  font-size: 6.5px;\n  opacity: 0.85;\n  color: var(--screen-text, #0f380f);\n  display: flex;\n  justify-content: space-between;\n  margin-top: 2px;\n}\n\n/* Creature Themes Grid */\n.poyori-theme-grid {\n  display: grid;\n  grid-template-columns: repeat(2, 1fr);\n  gap: 4px;\n  margin-top: 6px;\n}\n\n.theme-swatch-btn {\n  padding: 5px 4px;\n  font-family: 'PixelOperator8', monospace;\n  font-size: 7px;\n  border: 1px solid var(--screen-card-border, rgba(0, 0, 0, 0.2));\n  border-radius: 3px;\n  cursor: pointer;\n  text-align: center;\n}\n\n.theme-swatch-btn.active {\n  border: 2px solid #ffffff;\n  box-shadow: 0 0 6px rgba(0, 0, 0, 0.4);\n}\n\n/* Tamagotchi Size Selector & Live Preview Box */\n.size-preview-box {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  margin: 6px 0 12px 0;\n  background: var(--screen-card-bg, rgba(0, 0, 0, 0.05));\n  border: 1.5px solid var(--screen-card-border, rgba(0, 0, 0, 0.2));\n  border-radius: 4px;\n  padding: 6px 8px;\n}\n\n.size-preview-stage {\n  width: 72px;\n  height: 72px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  background: rgba(0, 0, 0, 0.12);\n  border-radius: 3px;\n  border: 1px solid var(--screen-card-border, rgba(0, 0, 0, 0.2));\n  overflow: hidden;\n  flex-shrink: 0;\n}\n\n.size-preview-sprite {\n  image-rendering: pixelated;\n  transition: width 0.2s ease, height 0.2s ease;\n  filter: drop-shadow(0 2px 3px rgba(0, 0, 0, 0.3));\n}\n\n.poyori-size-grid {\n  display: grid;\n  grid-template-columns: repeat(2, 1fr);\n  gap: 5px;\n  flex: 1;\n}\n\n.size-swatch-btn {\n  padding: 6px 4px;\n  font-family: 'PixelOperator8', monospace;\n  font-size: 7px;\n  border: 1.5px solid var(--screen-card-border, rgba(0, 0, 0, 0.25));\n  background: var(--screen-card-bg, rgba(0, 0, 0, 0.06));\n  color: var(--screen-text, #0f380f);\n  cursor: pointer;\n  border-radius: 3px;\n  text-align: center;\n  line-height: 1.3;\n  transition: all 0.1s;\n}\n\n.size-swatch-btn:hover {\n  border-color: #45b7b8;\n  background: rgba(69, 183, 184, 0.15);\n}\n\n.size-swatch-btn.active {\n  border-color: #fedb72;\n  background: #241b16;\n  color: #fedb72;\n  box-shadow: 0 0 6px rgba(254, 219, 114, 0.45);\n  font-weight: bold;\n}\n\n/* Companion Roster (Clean Uncluttered RPG Layout) */\n.poyori-roster-list {\n  display: flex;\n  flex-direction: column;\n  gap: 5px;\n  margin-top: 6px;\n}\n\n.poyori-roster-item {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  padding: 6px 8px;\n  background: var(--screen-card-bg, rgba(0, 0, 0, 0.05));\n  border: 1.5px solid var(--screen-card-border, rgba(0, 0, 0, 0.2));\n  border-radius: 4px;\n  transition: border-color 0.1s, box-shadow 0.1s;\n}\n\n.poyori-roster-item.active {\n  border-color: #27ae60;\n  box-shadow: 0 0 4px rgba(39, 174, 96, 0.25);\n}\n\n.roster-avatar {\n  width: 28px;\n  height: 28px;\n  image-rendering: pixelated;\n  flex-shrink: 0;\n  background: rgba(0, 0, 0, 0.1);\n  border-radius: 3px;\n  padding: 2px;\n}\n\n.roster-info {\n  display: flex;\n  flex-direction: column;\n  gap: 3px;\n  flex: 1;\n  min-width: 0;\n}\n\n.roster-name-row {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n}\n\n.roster-name {\n  font-family: 'PixelOperator8', monospace;\n  font-size: 8.5px;\n  font-weight: bold;\n  color: var(--screen-text, #0f380f);\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.roster-rename-btn {\n  font-family: 'PixelOperator8', monospace;\n  font-size: 6.5px;\n  color: var(--screen-label, #8c3d12);\n  background: rgba(0, 0, 0, 0.08);\n  border: 1px solid var(--screen-card-border, rgba(0, 0, 0, 0.2));\n  border-radius: 2px;\n  padding: 1px 4px;\n  cursor: pointer;\n  opacity: 0.9;\n  transition: all 0.1s;\n}\n\n.roster-rename-btn:hover {\n  opacity: 1;\n  border-color: #fedb72;\n  color: #fedb72;\n  background: #241b16;\n}\n\n.roster-sub-row {\n  display: flex;\n  align-items: center;\n}\n\n.roster-stage {\n  font-family: 'PixelOperator8', monospace;\n  font-size: 7px;\n  opacity: 0.85;\n  color: var(--screen-text, #0f380f);\n}\n\n.roster-action {\n  flex-shrink: 0;\n}\n\n.roster-active-badge {\n  font-family: 'PixelOperator8', monospace;\n  font-size: 7.5px;\n  color: #27ae60;\n  font-weight: bold;\n  display: flex;\n  align-items: center;\n  gap: 3px;\n}\n\n.switch-roster-btn {\n  font-family: 'PixelOperator8', monospace;\n  font-size: 7.5px;\n  padding: 4px 8px;\n  background: #2980b9;\n  color: #ffffff;\n  border: 1px solid #1a5276;\n  border-radius: 3px;\n  cursor: pointer;\n  transition: background 0.1s;\n}\n\n.switch-roster-btn:hover {\n  background: #3498db;\n}\n\n/* Global Font Size Scale overrides */\n:host(.font-size-large) .poyori-handheld-container,\n.font-size-large .poyori-handheld-container {\n  zoom: 1.15;\n}\n:host(.font-size-huge) .poyori-handheld-container,\n.font-size-huge .poyori-handheld-container {\n  zoom: 1.30;\n}\n}\n";
  const INLINED_CELEBRATION_CSS = "/**\n * Poyori (ポヨリ) — Celebratory Reward & Evolution Modal Styles\n * Pixel-art golden plaques, sunburst rays, glowing confetti sparkles,\n * and high-contrast retro RPG typography.\n */\n\n.poyori-celebrate-overlay {\n  position: fixed;\n  inset: 0;\n  background: rgba(10, 12, 18, 0.88);\n  backdrop-filter: blur(4px);\n  z-index: 2147483647;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  pointer-events: auto !important;\n  animation: celebrate-fade-in 0.2s ease-out;\n}\n\n@keyframes celebrate-fade-in {\n  from { opacity: 0; }\n  to { opacity: 1; }\n}\n\n@keyframes celebrate-dialog-pop {\n  0% { transform: scale(0.85); opacity: 0; }\n  70% { transform: scale(1.04); opacity: 1; }\n  100% { transform: scale(1); }\n}\n\n.poyori-celebrate-dialog {\n  position: relative;\n  width: 320px;\n  max-width: 90vw;\n  background: linear-gradient(180deg, #1c2333 0%, #0e121a 100%);\n  border: 4px solid #fedb72;\n  border-radius: 8px;\n  box-shadow: 0 0 0 3px #24140e, 0 12px 36px rgba(0, 0, 0, 0.85), 0 0 25px rgba(254, 219, 114, 0.35);\n  padding: 22px 18px 18px;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  text-align: center;\n  font-family: 'PixelOperator', monospace;\n  color: #f5e4c8;\n  user-select: none;\n  pointer-events: auto !important;\n  animation: celebrate-dialog-pop 0.32s cubic-bezier(0.175, 0.885, 0.32, 1.275);\n}\n\n/* Floating Sparkle Particles */\n.celebrate-sparkle {\n  position: absolute;\n  pointer-events: none;\n  animation: sparkle-float 1.8s infinite ease-in-out;\n}\n\n.celebrate-sparkle.sp-1 { top: -14px; left: 16px; animation-delay: 0s; }\n.celebrate-sparkle.sp-2 { top: 12px; right: 14px; animation-delay: 0.4s; }\n.celebrate-sparkle.sp-3 { bottom: 20px; left: 14px; animation-delay: 0.8s; }\n.celebrate-sparkle.sp-4 { bottom: -12px; right: 28px; animation-delay: 1.2s; }\n\n@keyframes sparkle-float {\n  0%, 100% { transform: translateY(0) scale(0.9); opacity: 0.7; }\n  50% { transform: translateY(-8px) scale(1.25); opacity: 1; filter: drop-shadow(0 0 4px #fedb72); }\n}\n\n/* Close button */\n.celebrate-close-btn {\n  position: absolute;\n  top: 8px;\n  right: 10px;\n  background: none;\n  border: none;\n  color: #a4b0be;\n  font-family: 'PixelOperator8', monospace;\n  font-size: 14px;\n  cursor: pointer;\n  line-height: 1;\n  padding: 4px 6px;\n  border-radius: 4px;\n}\n\n.celebrate-close-btn:hover {\n  color: #ff7675;\n  background: rgba(255, 118, 117, 0.15);\n}\n\n/* Badge Banner */\n.celebrate-badge-wrap {\n  margin-bottom: 8px;\n}\n\n.celebrate-badge {\n  display: inline-block;\n  background: #d63d2f;\n  color: #ffffff;\n  font-family: 'PixelOperator8', monospace;\n  font-size: 8px;\n  padding: 4px 10px;\n  border-radius: 4px;\n  border: 1px solid #fedb72;\n  box-shadow: 0 2px 0 #24140e, 0 0 10px rgba(214, 61, 47, 0.6);\n  letter-spacing: 0.5px;\n}\n\n/* Titles */\n.celebrate-title {\n  font-family: 'PixelOperator8', monospace;\n  font-size: 12px;\n  color: #fedb72;\n  text-shadow: 1px 1px 0 #24140e;\n  margin: 0 0 4px;\n  line-height: 1.4;\n}\n\n.celebrate-subtitle {\n  font-family: 'PixelOperator', monospace;\n  font-size: 14px;\n  font-weight: bold;\n  color: #81ecec;\n  margin-bottom: 12px;\n}\n\n/* Spotlight Stage */\n.celebrate-stage {\n  position: relative;\n  width: 100px;\n  height: 100px;\n  margin: 4px 0 12px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n}\n\n.celebrate-sunburst {\n  position: absolute;\n  inset: -15px;\n  background: radial-gradient(circle, rgba(254, 219, 114, 0.25) 0%, rgba(254, 219, 114, 0) 70%);\n  border-radius: 50%;\n  animation: sunburst-glow 2s infinite alternate ease-in-out;\n  pointer-events: none;\n}\n\n@keyframes sunburst-glow {\n  0% { transform: scale(0.9); opacity: 0.6; }\n  100% { transform: scale(1.15); opacity: 1; }\n}\n\n.celebrate-pedestal {\n  position: absolute;\n  bottom: 8px;\n  width: 64px;\n  height: 14px;\n  background: #24140e;\n  border: 2px solid #fedb72;\n  border-radius: 50%;\n  box-shadow: 0 3px 6px rgba(0, 0, 0, 0.6);\n}\n\n.celebrate-sprite {\n  width: 64px;\n  height: 64px;\n  image-rendering: pixelated;\n  z-index: 2;\n  animation: celebrate-sprite-bounce 0.8s infinite alternate ease-in-out;\n}\n\n.celebrate-icon-wrap {\n  z-index: 2;\n  animation: celebrate-sprite-bounce 0.8s infinite alternate ease-in-out;\n}\n\n@keyframes celebrate-sprite-bounce {\n  0% { transform: translateY(0); }\n  100% { transform: translateY(-8px); }\n}\n\n/* Meta Details Box */\n.celebrate-info-box {\n  width: 100%;\n  background: #151924;\n  border: 1px solid #353d52;\n  border-radius: 6px;\n  padding: 10px 12px;\n  margin-bottom: 14px;\n  box-sizing: border-box;\n}\n\n.celebrate-stage-tag {\n  font-family: 'PixelOperator8', monospace;\n  font-size: 8px;\n  color: #ffeaa7;\n  margin-bottom: 4px;\n}\n\n.celebrate-branch-tag {\n  font-family: 'PixelOperator8', monospace;\n  font-size: 8px;\n  color: #74b9ff;\n  margin-bottom: 6px;\n}\n\n.celebrate-cost-tag {\n  font-size: 12px;\n  color: #fedb72;\n  margin-bottom: 6px;\n}\n\n.celebrate-desc {\n  font-size: 11px;\n  color: #d1d8e0;\n  line-height: 1.5;\n  margin: 0;\n}\n\n/* Actions */\n.celebrate-actions {\n  width: 100%;\n}\n\n.celebrate-action-btn {\n  width: 100%;\n  background: #d88344;\n  color: #ffffff;\n  border: 2px solid #24140e;\n  border-radius: 4px;\n  padding: 10px 14px;\n  font-family: 'PixelOperator8', monospace;\n  font-size: 9px;\n  cursor: pointer;\n  box-shadow: inset 0 2px 0 #f2ad6e, 0 3px 0 #000;\n  text-shadow: 1px 1px 0 #24140e;\n  transition: all 0.1s ease;\n}\n\n.celebrate-action-btn:hover {\n  background: #e89555;\n  transform: translateY(-1px);\n}\n\n.celebrate-action-btn:active {\n  transform: translateY(2px);\n  box-shadow: 0 1px 0 #000;\n}\n\n/* Companion Naming Box */\n.celebrate-naming-box {\n  width: 100%;\n  background: #11141d;\n  border: 1px dashed #4b5563;\n  border-radius: 6px;\n  padding: 8px 10px;\n  margin-bottom: 12px;\n  box-sizing: border-box;\n  text-align: left;\n}\n\n.celebrate-naming-label {\n  display: block;\n  font-family: 'PixelOperator8', monospace;\n  font-size: 8px;\n  color: #ffeaa7;\n  margin-bottom: 5px;\n}\n\n.celebrate-naming-input-row {\n  width: 100%;\n}\n\n.celebrate-name-input {\n  width: 100%;\n  box-sizing: border-box;\n  background: #1e2433;\n  color: #f1f2f6;\n  border: 1px solid #4b5563;\n  border-radius: 4px;\n  padding: 6px 8px;\n  font-family: 'PixelOperator', monospace, sans-serif;\n  font-size: 13px;\n  outline: none;\n  transition: border-color 0.15s ease;\n}\n\n.celebrate-name-input:focus {\n  border-color: #00f0ff;\n  box-shadow: 0 0 4px rgba(0, 240, 255, 0.4);\n}\n\n.celebrate-naming-hint {\n  font-size: 9px;\n  color: #9ca3af;\n  margin-top: 4px;\n}\n\n";

