// Helper to encode SVG to base64
function toBase64(str) {
  if (typeof btoa === 'function') {
    return btoa(str);
  }
  if (typeof Buffer !== 'undefined') {
    return Buffer.from(str).toString('base64');
  }
  return encodeURIComponent(str);
}

